  1	const std = @import("std");
  2	
  3	pub const Error = error{
  4	    InvalidMetadata,
  5	};
  6	
  7	fn readLe(comptime T: type, buf: []const u8, offset: usize) Error!T {
  8	    const size = @sizeOf(T);
  9	    const end = std.math.add(usize, offset, size) catch return error.InvalidMetadata;
 10	    if (end > buf.len) return error.InvalidMetadata;
 11	    return std.mem.readInt(T, @ptrCast(buf[offset..end]), .little);
 12	}
 13	
 14	pub fn readU8(buf: []const u8, offset: usize) Error!u8 {
 15	    if (offset >= buf.len) return error.InvalidMetadata;
 16	    return buf[offset];
 17	}
 18	
 19	pub fn readU16(buf: []const u8, offset: usize) Error!u16 {
 20	    return readLe(u16, buf, offset);
 21	}
 22	
 23	pub fn readI16(buf: []const u8, offset: usize) Error!i16 {
 24	    return readLe(i16, buf, offset);
 25	}
 26	
 27	pub fn readU32(buf: []const u8, offset: usize) Error!u32 {
 28	    return readLe(u32, buf, offset);
 29	}
 30	
 31	pub fn readI32(buf: []const u8, offset: usize) Error!i32 {
 32	    return readLe(i32, buf, offset);
 33	}
 34	
 35	pub fn readI64(buf: []const u8, offset: usize) Error!i64 {
 36	    return readLe(i64, buf, offset);
 37	}
 38	
 39	pub const Table = struct {
 40	    buf: []const u8,
 41	    object_start: usize,
 42	    vtable_start: usize,
 43	    vtable_len: usize,
 44	    object_len: usize,
 45	
 46	    /// Return absolute field offset in the underlying buffer.
 47	    pub fn fieldAbsOffset(self: Table, field_id: usize) ?usize {
 48	        const field_slot_start = std.math.add(usize, 4, field_id * 2) catch return null;
 49	        if (field_slot_start + 2 > self.vtable_len) return null;
 50	
 51	        const rel = readU16(self.buf, self.vtable_start + field_slot_start) catch return null;
 52	        if (rel == 0) return null;
 53	
 54	        const abs = std.math.add(usize, self.object_start, rel) catch return null;
 55	        if (abs >= self.buf.len) return null;
 56	        return abs;
 57	    }
 58	
 59	    pub fn readFieldU8(self: Table, field_id: usize) ?u8 {
 60	        const abs = self.fieldAbsOffset(field_id) orelse return null;
 61	        return readU8(self.buf, abs) catch null;
 62	    }
 63	
 64	    pub fn readFieldI16(self: Table, field_id: usize) ?i16 {
 65	        const abs = self.fieldAbsOffset(field_id) orelse return null;
 66	        return readI16(self.buf, abs) catch null;
 67	    }
 68	
 69	    pub fn readFieldI64(self: Table, field_id: usize) ?i64 {
 70	        const abs = self.fieldAbsOffset(field_id) orelse return null;
 71	        return readI64(self.buf, abs) catch null;
 72	    }
 73	};
 74	
 75	pub fn rootTable(buf: []const u8) Error!Table {
 76	    if (buf.len < 8) return error.InvalidMetadata;
 77	
 78	    const root_off_u32 = try readU32(buf, 0);
 79	    const root_off = std.math.cast(usize, root_off_u32) orelse return error.InvalidMetadata;
 80	    if (root_off > buf.len - 4) return error.InvalidMetadata;
 81	
 82	    const vtable_rel_i32 = try readI32(buf, root_off);
 83	    if (vtable_rel_i32 <= 0) return error.InvalidMetadata;
 84	    const vtable_rel = std.math.cast(usize, vtable_rel_i32) orelse return error.InvalidMetadata;
 85	    if (vtable_rel > root_off) return error.InvalidMetadata;
 86	
 87	    const vtable_start = root_off - vtable_rel;
 88	    if (vtable_start > buf.len - 4) return error.InvalidMetadata;
 89	
 90	    const vtable_len_u16 = try readU16(buf, vtable_start);
 91	    const object_len_u16 = try readU16(buf, vtable_start + 2);
 92	    if (vtable_len_u16 < 4) return error.InvalidMetadata;
 93	    if (object_len_u16 == 0) return error.InvalidMetadata;
 94	
 95	    const vtable_len = @as(usize, vtable_len_u16);
 96	    const object_len = @as(usize, object_len_u16);
 97	    if (vtable_start + vtable_len > buf.len) return error.InvalidMetadata;
 98	    if (root_off + object_len > buf.len) return error.InvalidMetadata;
 99	
100	    return .{
101	        .buf = buf,
102	        .object_start = root_off,
103	        .vtable_start = vtable_start,
104	        .vtable_len = vtable_len,
105	        .object_len = object_len,
106	    };
107	}
