112	        0xff, 0xff, 0xff, 0xff,
113	    };
114	    try std.testing.expectError(error.InvalidMetadata, rootTable(malformed[0..]));
115	}
  1	const std = @import("std");
  2	const reader = @import("reader.zig");
  3	
  4	pub const Error = error{
  5	    InvalidMetadata,
  6	};
  7	
  8	pub const MessageEnvelope = struct {
  9	    version: i16,
 10	    header_type: u8,
 11	    body_length: i64,
 12	};
 13	
 14	/// Fast structural sanity check for any FlatBuffer table blob.
 15	pub fn isSaneTable(buf: []const u8) bool {
 16	    _ = reader.rootTable(buf) catch return false;
 17	    return true;
 18	}
 19	
 20	/// Parse + validate Arrow IPC Message envelope fields without full unpack.
 21	///
 22	/// Message.fbs field ids:
 23	/// 0 = version (enum MetadataVersion: short)
 24	/// 1 = header_type (union discriminator)
 25	/// 3 = bodyLength (long)
 26	pub fn parseArrowMessageEnvelope(buf: []const u8) Error!MessageEnvelope {
 27	    const table = reader.rootTable(buf) catch return error.InvalidMetadata;
 28	
 29	    const version = table.readFieldI16(0) orelse 0;
 30	    if (version < 0 or version > 4) return error.InvalidMetadata;
 31	
 32	    const header_type = table.readFieldU8(1) orelse return error.InvalidMetadata;
 33	    if (header_type == 0) return error.InvalidMetadata;
 34	
 35	    const body_length = table.readFieldI64(3) orelse 0;
 36	
 37	    return .{
 38	        .version = version,
 39	        .header_type = header_type,
 40	        .body_length = body_length,
 41	    };
 42	}
 43	
 44	// ---------------------------------------------------------------------------------------------
 45	// Full verifier for Message and Footer flatbuffers.
 46	//
 47	// The generated readers in src/ipc_schema (and fbs_runtime's Table) trust every offset, length
 48	// and enum value they read: a bad offset slices out of bounds (a panic in safe builds, an
 49	// out-of-bounds read in ReleaseFast) and an unknown enum value panics. `unpackMessage` /
 50	// `unpackFooter` therefore run these checks first, like Arrow C++ runs flatbuffers' Verifier:
 51	// every table, vtable, field, string, vector and union reachable by the unpackers must lie inside
 52	// the buffer, every enum / union tag must be a value the generated enum declares, nesting depth
 53	// is capped and the number of tables visited is bounded by the buffer size (shared subtables
 54	// cannot make the unpack exponential).
 55	//
 56	// When the schema is regenerated with new fields, the comptime field counts below stop compiling:
 57	// add the new fields here before the unpackers can read them unchecked.
 58	
 59	const fbs = struct {
 60	    const s = @import("ipc_schema");
 61	    const Message = s.org_apache_arrow_flatbuf_Message;
 62	    const MessageHeader = s.org_apache_arrow_flatbuf_MessageHeader.MessageHeader;
 63	    const MetadataVersion = s.org_apache_arrow_flatbuf_MetadataVersion.MetadataVersion;
 64	    const Type = s.org_apache_arrow_flatbuf_Type.Type;
 65	    const SparseTensorIndex = s.org_apache_arrow_flatbuf_SparseTensorIndex.SparseTensorIndex;
 66	    const Endianness = s.org_apache_arrow_flatbuf_Endianness.Endianness;
 67	    const Precision = s.org_apache_arrow_flatbuf_Precision.Precision;
 68	    const DateUnit = s.org_apache_arrow_flatbuf_DateUnit.DateUnit;
 69	    const TimeUnit = s.org_apache_arrow_flatbuf_TimeUnit.TimeUnit;
 70	    const IntervalUnit = s.org_apache_arrow_flatbuf_IntervalUnit.IntervalUnit;
 71	    const UnionMode = s.org_apache_arrow_flatbuf_UnionMode.UnionMode;
 72	    const DictionaryKind = s.org_apache_arrow_flatbuf_DictionaryKind.DictionaryKind;
 73	    const CompressionType = s.org_apache_arrow_flatbuf_CompressionType.CompressionType;
 74	    const BodyCompressionMethod = s.org_apache_arrow_flatbuf_BodyCompressionMethod.BodyCompressionMethod;
 75	    const SparseMatrixCompressedAxis = s.org_apache_arrow_flatbuf_SparseMatrixCompressedAxis.SparseMatrixCompressedAxis;
 76	};
 77	
 78	comptime {
 79	    // Field count of every table the verifier walks (union type+value pairs count once).
 80	    const counts = .{
 81	        .{ fbs.s.org_apache_arrow_flatbuf_Message.MessageT, 4 },
 82	        .{ fbs.s.org_apache_arrow_flatbuf_Schema.SchemaT, 4 },
 83	        .{ fbs.s.org_apache_arrow_flatbuf_Field.FieldT, 6 },
 84	        .{ fbs.s.org_apache_arrow_flatbuf_KeyValue.KeyValueT, 2 },
 85	        .{ fbs.s.org_apache_arrow_flatbuf_DictionaryEncoding.DictionaryEncodingT, 4 },
 86	        .{ fbs.s.org_apache_arrow_flatbuf_RecordBatch.RecordBatchT, 5 },
 87	        .{ fbs.s.org_apache_arrow_flatbuf_BodyCompression.BodyCompressionT, 2 },
 88	        .{ fbs.s.org_apache_arrow_flatbuf_DictionaryBatch.DictionaryBatchT, 3 },
 89	        .{ fbs.s.org_apache_arrow_flatbuf_Tensor.TensorT, 4 },
 90	        .{ fbs.s.org_apache_arrow_flatbuf_TensorDim.TensorDimT, 2 },
 91	        .{ fbs.s.org_apache_arrow_flatbuf_SparseTensor.SparseTensorT, 5 },
 92	        .{ fbs.s.org_apache_arrow_flatbuf_SparseTensorIndexCOO.SparseTensorIndexCOOT, 4 },
 93	        .{ fbs.s.org_apache_arrow_flatbuf_SparseMatrixIndexCSX.SparseMatrixIndexCSXT, 5 },
 94	        .{ fbs.s.org_apache_arrow_flatbuf_SparseTensorIndexCSF.SparseTensorIndexCSFT, 5 },
 95	        .{ fbs.s.org_apache_arrow_flatbuf_Footer.FooterT, 5 },
 96	        .{ fbs.s.org_apache_arrow_flatbuf_Int.IntT, 2 },
 97	        .{ fbs.s.org_apache_arrow_flatbuf_Decimal.DecimalT, 3 },
 98	        .{ fbs.s.org_apache_arrow_flatbuf_Time.TimeT, 2 },
 99	        .{ fbs.s.org_apache_arrow_flatbuf_Timestamp.TimestampT, 2 },
100	        .{ fbs.s.org_apache_arrow_flatbuf_Union.UnionT, 2 },
101	    };
102	    for (counts) |c| {
103	        if (std.meta.fieldNames(c[0]).len != c[1]) @compileError("fbs_lite/verify.zig does not cover every field of " ++ @typeName(c[0]));
104	    }
105	    if (std.meta.fieldNames(fbs.Type).len != 27) @compileError("verifyType does not cover every Type union member");
106	}
