108	const max_depth = 128;
109	
110	const Verifier = struct {
111	    buf: []const u8,
112	    depth: u32 = 0,
113	    tables_left: usize,
114	
115	    fn need(v: *const Verifier, pos: usize, len: usize) Error!void {
116	        const end = std.math.add(usize, pos, len) catch return error.InvalidMetadata;
117	        if (end > v.buf.len) return error.InvalidMetadata;
118	    }
119	
120	    fn int(v: *const Verifier, comptime T: type, pos: usize) Error!T {
121	        try v.need(pos, @sizeOf(T));
122	        return std.mem.readInt(T, v.buf[pos..][0..@sizeOf(T)], .little);
123	    }
124	
125	    const Tab = struct { pos: usize, vtable: usize, vtable_len: usize };
126	
127	    fn table(v: *Verifier, pos: usize) Error!Tab {
128	        if (v.tables_left == 0) return error.InvalidMetadata;
129	        v.tables_left -= 1;
130	        const vtable_i = @as(i64, @intCast(pos)) - try v.int(i32, pos);
131	        const vtable = std.math.cast(usize, vtable_i) orelse return error.InvalidMetadata;
132	        const vtable_len = try v.int(u16, vtable);
133	        if (vtable_len < 4 or vtable_len % 2 != 0) return error.InvalidMetadata;
134	        try v.need(vtable, vtable_len);
135	        return .{ .pos = pos, .vtable = vtable, .vtable_len = vtable_len };
136	    }
137	
138	    /// Absolute position of field `id` (null when absent); its `size` bytes must be in bounds.
139	    fn field(v: *Verifier, t: Tab, id: usize, size: usize) Error!?usize {
140	        const slot = 4 + 2 * id;
141	        if (slot >= t.vtable_len) return null;
142	        const rel = try v.int(u16, t.vtable + slot);
143	        if (rel == 0) return null;
144	        try v.need(t.pos + rel, size);
145	        return t.pos + rel;
146	    }
147	
148	    fn scalar(v: *Verifier, t: Tab, id: usize, comptime T: type) Error!void {
149	        _ = try v.field(t, id, @sizeOf(T));
150	    }
151	
152	    /// Enum (or union tag) field: must decode to a declared value of `E`, as fbs_runtime reads it.
153	    fn enumField(v: *Verifier, t: Tab, id: usize, comptime E: type) Error!?E {
154	        const tag_int = @typeInfo(@typeInfo(E).@"enum".tag_type).int;
155	        const I = @Int(tag_int.signedness, std.math.ceilPowerOfTwo(u16, @max(tag_int.bits, 8)) catch unreachable);
156	        const pos = try v.field(t, id, @sizeOf(I)) orelse return null;
157	        return std.enums.fromInt(E, try v.int(I, pos)) orelse error.InvalidMetadata;
158	    }
159	
160	    /// Target of the uoffset stored in field `id` (null when absent).
161	    fn indirect(v: *Verifier, t: Tab, id: usize) Error!?usize {
162	        const pos = try v.field(t, id, 4) orelse return null;
163	        return try v.follow(pos);
164	    }
165	
166	    fn follow(v: *Verifier, pos: usize) Error!usize {
167	        const target = std.math.add(usize, pos, try v.int(u32, pos)) catch return error.InvalidMetadata;
168	        try v.need(target, 4);
169	        return target;
170	    }
171	
172	    fn nested(v: *Verifier, pos: usize, comptime verifyFn: fn (*Verifier, Tab) Error!void) Error!void {
173	        if (v.depth >= max_depth) return error.InvalidMetadata;
174	        v.depth += 1;
175	        defer v.depth -= 1;
176	        try verifyFn(v, try v.table(pos));
177	    }
178	
179	    fn subTable(v: *Verifier, t: Tab, id: usize, comptime verifyFn: fn (*Verifier, Tab) Error!void) Error!void {
180	        if (try v.indirect(t, id)) |pos| try v.nested(pos, verifyFn);
181	    }
182	
183	    /// Vector of `elem_size`-byte elements (strings are byte vectors); returns start and length.
184	    fn vector(v: *Verifier, t: Tab, id: usize, elem_size: usize) Error!?struct { start: usize, len: usize } {
185	        const pos = try v.indirect(t, id) orelse return null;
186	        const len = try v.int(u32, pos);
187	        try v.need(pos + 4, std.math.mul(usize, len, elem_size) catch return error.InvalidMetadata);
188	        return .{ .start = pos + 4, .len = len };
189	    }
190	
191	    fn tableVector(v: *Verifier, t: Tab, id: usize, comptime verifyFn: fn (*Verifier, Tab) Error!void) Error!void {
192	        const vec = try v.vector(t, id, 4) orelse return;
193	        for (0..vec.len) |i| try v.nested(try v.follow(vec.start + 4 * i), verifyFn);
194	    }
195	
196	    fn unionValue(v: *Verifier, t: Tab, type_id: usize, comptime U: type, comptime verifyFn: fn (*Verifier, std.meta.Tag(U), Tab) Error!void) Error!void {
197	        // The unpackers follow the value offset whenever it is present, even for a NONE tag.
198	        const pos = try v.indirect(t, type_id + 1) orelse return;
199	        const tag = try v.enumField(t, type_id, std.meta.Tag(U)) orelse return;
200	        if (v.depth >= max_depth) return error.InvalidMetadata;
201	        v.depth += 1;
202	        defer v.depth -= 1;
203	        try verifyFn(v, tag, try v.table(pos));
204	    }
205	};
206	
207	fn verifyKeyValue(v: *Verifier, t: Verifier.Tab) Error!void {
208	    _ = try v.vector(t, 0, 1);
209	    _ = try v.vector(t, 1, 1);
210	}
211	
212	fn verifyInt(v: *Verifier, t: Verifier.Tab) Error!void {
213	    try v.scalar(t, 0, i32);
214	    try v.scalar(t, 1, bool);
215	}
216	
217	fn verifyType(v: *Verifier, tag: std.meta.Tag(fbs.Type), t: Verifier.Tab) Error!void {
218	    switch (tag) {
219	        .NONE, .Null, .Binary, .Utf8, .Bool, .List, .Struct_, .LargeBinary, .LargeUtf8, .LargeList, .RunEndEncoded, .BinaryView, .Utf8View, .ListView, .LargeListView => {},
220	        .Int => try verifyInt(v, t),
221	        .FloatingPoint => _ = try v.enumField(t, 0, fbs.Precision),
222	        .Decimal => for (0..3) |id| try v.scalar(t, id, i32),
223	        .Date => _ = try v.enumField(t, 0, fbs.DateUnit),
224	        .Time => {
225	            _ = try v.enumField(t, 0, fbs.TimeUnit);
226	            try v.scalar(t, 1, i32);
227	        },
228	        .Timestamp => {
229	            _ = try v.enumField(t, 0, fbs.TimeUnit);
230	            _ = try v.vector(t, 1, 1);
231	        },
232	        .Interval => _ = try v.enumField(t, 0, fbs.IntervalUnit),
233	        .Union => {
234	            _ = try v.enumField(t, 0, fbs.UnionMode);
235	            _ = try v.vector(t, 1, 4);
236	        },
237	        .FixedSizeBinary, .FixedSizeList => try v.scalar(t, 0, i32),
238	        .Map => try v.scalar(t, 0, bool),
239	        .Duration => _ = try v.enumField(t, 0, fbs.TimeUnit),
240	    }
241	}
242	
243	fn verifyDictionaryEncoding(v: *Verifier, t: Verifier.Tab) Error!void {
244	    try v.scalar(t, 0, i64);
245	    try v.subTable(t, 1, verifyInt);
246	    try v.scalar(t, 2, bool);
247	    _ = try v.enumField(t, 3, fbs.DictionaryKind);
248	}
249	
250	fn verifyField(v: *Verifier, t: Verifier.Tab) Error!void {
251	    _ = try v.vector(t, 0, 1);
252	    try v.scalar(t, 1, bool);
253	    try v.unionValue(t, 2, fbs.Type, verifyType);
254	    try v.subTable(t, 4, verifyDictionaryEncoding);
255	    try v.tableVector(t, 5, verifyField);
256	    try v.tableVector(t, 6, verifyKeyValue);
257	}
258	
259	fn verifySchema(v: *Verifier, t: Verifier.Tab) Error!void {
260	    _ = try v.enumField(t, 0, fbs.Endianness);
261	    try v.tableVector(t, 1, verifyField);
262	    try v.tableVector(t, 2, verifyKeyValue);
263	    _ = try v.vector(t, 3, 8);
264	}
265	
266	fn verifyBodyCompression(v: *Verifier, t: Verifier.Tab) Error!void {
267	    _ = try v.enumField(t, 0, fbs.CompressionType);
268	    _ = try v.enumField(t, 1, fbs.BodyCompressionMethod);
269	}
270	
271	fn verifyRecordBatch(v: *Verifier, t: Verifier.Tab) Error!void {
272	    try v.scalar(t, 0, i64);
273	    _ = try v.vector(t, 1, 16); // FieldNode
274	    _ = try v.vector(t, 2, 16); // Buffer
275	    try v.subTable(t, 3, verifyBodyCompression);
276	    _ = try v.vector(t, 4, 8);
277	}
278	
279	fn verifyDictionaryBatch(v: *Verifier, t: Verifier.Tab) Error!void {
280	    try v.scalar(t, 0, i64);
281	    try v.subTable(t, 1, verifyRecordBatch);
282	    try v.scalar(t, 2, bool);
283	}
284	
