#!/bin/bash
# usage: compat_replay.sh <zarrow-fuzz.exe> <out.tsv>
# Replays every arrow-testing IPC input one at a time; prints target, file, error, batches, validateFull.
exe="$1"; out="$2"
D=/c/Users/cable/AppData/Local/Temp/arrow-testing/data
: > "$out"
one() {
  local t="$1" f="$2"
  line=$("$exe" "$t" replay "$f" 2>&1 | grep -a "batches, validateFull" | tail -1)
  res=${line##*: }
  rest=${line%, validateFull*}
  err=${rest%%, *}; err=${err##*: }
  b=${rest##*, }; b=${b%% *}
  vf=${line##*validateFull: }
  printf '%s\t%s\t%s\t%s\t%s\n' "$t" "${f#$D/}" "${err:-CRASH}" "$b" "$vf" >> "$out"
}
for f in "$D"/arrow-ipc-stream/*; do [ -f "$f" ] && [[ "$f" != *.md ]] && one ipc-stream "$f"; done
for f in "$D"/arrow-ipc-stream/integration/*/*.stream; do one ipc-stream "$f"; done
for f in "$D"/arrow-ipc-file/*; do [ -f "$f" ] && [[ "$f" != *.md ]] && one ipc-file "$f"; done
for f in "$D"/arrow-ipc-stream/integration/*/*.arrow_file; do one ipc-file "$f"; done
awk -F'\t' '{k=$1 (index($2,"integration/")?" integration":" reproducers"); n[k]++; if($3=="ok") ok[k]++} END{for(k in n) printf "%s: %d inputs, %d decoded, %d rejected\n", k, n[k], ok[k], n[k]-ok[k]}' "$out" | sort

