    const allocator = std.testing.allocator;
    const data = @embedFile("testdata/pyarrow_multi_batch_stream.arrow");

    var stream: std.Io.Reader = .fixed(data);
    var reader = StreamReader.init(allocator, &stream);
    defer reader.deinit();

